package dev.mineagent.runtime.core.building;
import java.nio.file.*;import java.util.*;
/** Explicit local read-only parser audit. No files are published or uploaded by this CLI. */
public final class BuildingCorpusCli {
 public static void main(String[] args)throws Exception{if(args.length<2||args.length>3)throw new IllegalArgumentException("root output.json");Path root=Path.of(args[0]);if(Files.isDirectory(root)&&Files.exists(root.resolve("level.dat"))){var metadata=AnvilBuildingReader.inspect(root,0);Path region=null;int slot=-1;try(var walk=Files.walk(root.resolve("region"))){for(var candidate:walk.filter(p->p.getFileName().toString().endsWith(".mca")).sorted().toList()){if(Files.size(candidate)<8192)continue;try(var f=new java.io.RandomAccessFile(candidate.toFile(),"r")){for(int i=0;i<1024;i++)if(f.readInt()!=0){slot=i;region=candidate;break;}}if(slot>=0)break;}}if(slot<0)throw new IllegalStateException("EMPTY_WORLD");String[] coords=region.getFileName().toString().split("\\.");int x=Integer.parseInt(coords[1])*512+slot%32*16,z=Integer.parseInt(coords[2])*512+slot/32*16;long[] blocks={0};var sample=AnvilBuildingReader.stream(root,"minecraft:overworld",new BuildingDocument.Bounds(new BuildingDocument.Pos(x,-64,z),new BuildingDocument.Pos(x+15,319,z+15)),false,b->blocks[0]++,()->true);Files.writeString(Path.of(args[1]),new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(Map.of("metadata",metadata,"sample",sample,"nonAir",blocks[0])));System.out.println("WORLD_COMPLETE sampleBlocks="+blocks[0]);return;}var files=new ArrayList<Path>();try(var walk=Files.walk(root)){walk.filter(p->Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS)&&p.getFileName().toString().endsWith(".litematic")).sorted().forEach(files::add);}long total=0;var fail=new ArrayList<Object>();var records=new ArrayList<Object>();int done=0;for(var p:files){try{var doc=BuildingDocument.read(p);long[] blocks={0};if(args.length<3||!args[2].equals("headers"))doc.stream(null,false,b->blocks[0]++,()->true);total+=blocks[0];records.add(Map.of("path",root.relativize(p).toString(),"blocks",blocks[0],"metadata",doc.metadata()));}catch(Exception e){fail.add(Map.of("path",root.relativize(p).toString(),"error",e.toString()));}if(++done%500==0)System.out.println("PARSED="+done+" ERRORS="+fail.size());}var value=Map.of("mode",args.length==3?args[2]:"full","files",files.size(),"parsed",records.size(),"nonAirBlockRecords",total,"failures",fail,"records",records);Files.writeString(Path.of(args[1]),new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(value));System.out.println("CORPUS_COMPLETE files="+files.size()+" parsed="+records.size()+" failures="+fail.size());}
 private BuildingCorpusCli(){}
}
